import * as THREE from 'three';
import { buildSoldier } from './soldier.js';

export const BOT_STATE = { PATROL: 0, ALERT: 1, COMBAT: 2, HUNT: 3, DEAD: 4 };

const _ray = new THREE.Raycaster();
const _dir = new THREE.Vector3();
const _fwd = new THREE.Vector3();

// AI bot. Simulated only on the host (or in solo play); other clients see a BotProxy.
// ctx: { targets: [{id, eye, pos}], solids, colliders, botFire(enemy, targetId, hit, dist), time }
export class Enemy {
  constructor(scene, spawn, id) {
    this.id = id;
    this.scene = scene;
    this.state = BOT_STATE.PATROL;
    this.hp = 100;
    this.waypoints = spawn.waypoints.map(([x, z]) => new THREE.Vector3(x, 0, z));
    this.wpIndex = 0;
    this.yaw = Math.random() * Math.PI * 2;
    this.targetYaw = this.yaw;
    this.visionTimer = Math.random() * 0.15;
    this.reactionTimer = 0;
    this.loseSightTimer = 0;
    this.burstLeft = 0;
    this.fireTimer = 1 + Math.random();
    this.lastKnown = null;
    this.targetId = null;
    this.deathT = 0;
    this._sees = false;
    this._spotted = null;

    this.group = new THREE.Group();
    this.group.position.set(spawn.pos[0], 0, spawn.pos[1]);
    const parts = buildSoldier(this.group, 'hostile');
    this.hitboxes = parts.hitboxes;
    for (const h of this.hitboxes) h.userData.enemy = this;
    this.head = parts.head;
    this.muzzle = parts.muzzle;
    this.legL = parts.legL;
    this.legR = parts.legR;
    scene.add(this.group);
  }

  get position() { return this.group.position; }
  get alive() { return this.state !== BOT_STATE.DEAD; }
  get headPos() { return this.head.getWorldPosition(new THREE.Vector3()); }

  netState() {
    const p = this.position;
    return [this.id, +p.x.toFixed(2), +p.z.toFixed(2), +this.yaw.toFixed(2), this.state, this.hp];
  }

  canSee(targetEye, solids, fovCheck = true) {
    const eye = this.headPos;
    _dir.copy(targetEye).sub(eye);
    const dist = _dir.length();
    if (dist > 30) return false;
    _dir.normalize();
    if (fovCheck) {
      // model faces -Z at yaw 0
      _fwd.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
      const flat = _dir.clone().setY(0).normalize();
      if (_fwd.dot(flat) < Math.cos(THREE.MathUtils.degToRad(60))) return false; // 120° FOV
    }
    _ray.set(eye, _dir);
    _ray.far = dist - 0.2;
    return _ray.intersectObjects(solids.children, false).length === 0;
  }

  pickTarget(ctx, fovCheck) {
    let best = null, bestDist = Infinity;
    for (const t of ctx.targets) {
      const d = this.position.distanceTo(t.pos);
      if (d < bestDist && this.canSee(t.eye, ctx.solids, fovCheck)) {
        best = t;
        bestDist = d;
      }
    }
    return best;
  }

  getTarget(ctx) {
    return ctx.targets.find(t => t.id === this.targetId) || null;
  }

  hearGunshot(pos) {
    if (this.alive && this.state === BOT_STATE.PATROL && this.position.distanceTo(pos) < 26) {
      this.lastKnown = pos.clone();
      this.state = BOT_STATE.HUNT;
    }
  }

  takeDamage(amount, fromPos) {
    if (!this.alive) return false;
    this.hp -= amount;
    if (fromPos) this.lastKnown = fromPos.clone();
    if (this.hp <= 0) {
      this.hp = 0;
      this.state = BOT_STATE.DEAD;
      this.deathT = 0;
      return true; // killed
    }
    if (this.state !== BOT_STATE.COMBAT) {
      this.state = BOT_STATE.COMBAT;
      this.reactionTimer = 0.25;
    }
    return false;
  }

  faceToward(dx, dz) { this.targetYaw = Math.atan2(-dx, -dz); }

  moveToward(target, speed, dt, colliders) {
    _dir.copy(target).sub(this.position).setY(0);
    const dist = _dir.length();
    if (dist < 0.4) return true;
    _dir.normalize();
    this.faceToward(_dir.x, _dir.z);
    const step = Math.min(speed * dt, dist);
    const nx = this.position.x + _dir.x * step;
    const nz = this.position.z + _dir.z * step;
    if (!this.collides(nx, this.position.z, colliders)) this.position.x = nx;
    if (!this.collides(this.position.x, nz, colliders)) this.position.z = nz;
    return false;
  }

  collides(x, z, colliders) {
    const r = 0.35;
    for (const box of colliders) {
      if (x + r > box.min.x && x - r < box.max.x &&
          z + r > box.min.z && z - r < box.max.z &&
          box.min.y < 1.5 && box.max.y > 0.2) return true;
    }
    return false;
  }

  animateLegs(time, speed) {
    const swing = Math.sin(time * speed * 4) * 0.3;
    this.legL.rotation.x = swing;
    this.legR.rotation.x = -swing;
  }

  update(dt, ctx) {
    if (!this.alive) {
      this.deathT = Math.min(1, this.deathT + dt * 2.6);
      const t = this.deathT;
      this.group.rotation.z = (Math.PI / 2) * t * t;
      this.group.position.y = -0.15 * t;
      return;
    }

    // smooth turn
    let dy = this.targetYaw - this.yaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    this.yaw += dy * Math.min(1, dt * 7);
    this.group.rotation.y = this.yaw;

    // vision at 8 Hz
    this.visionTimer -= dt;
    if (this.visionTimer <= 0) {
      this.visionTimer = 0.125;
      if (this.state === BOT_STATE.COMBAT || this.state === BOT_STATE.ALERT) {
        const t = this.getTarget(ctx);
        this._sees = !!t && this.canSee(t.eye, ctx.solids, false);
        if (!this._sees) {
          // current target hidden or gone — switch to any other visible one
          const nt = this.pickTarget(ctx, false);
          if (nt) { this.targetId = nt.id; this._sees = true; }
        }
      } else {
        const nt = this.pickTarget(ctx, true);
        this._spotted = nt ? nt.id : null;
      }
    }

    switch (this.state) {
      case BOT_STATE.PATROL: {
        const wp = this.waypoints[this.wpIndex];
        if (this.moveToward(wp, 1.5, dt, ctx.colliders)) {
          this.wpIndex = (this.wpIndex + 1) % this.waypoints.length;
        }
        this.animateLegs(ctx.time, 1.5);
        if (this._spotted !== null) {
          this.targetId = this._spotted;
          this._spotted = null;
          this.state = BOT_STATE.ALERT;
          this.reactionTimer = 0.35 + Math.random() * 0.25;
        }
        break;
      }
      case BOT_STATE.ALERT: {
        const t = this.getTarget(ctx);
        if (!t || !this._sees) { this.state = BOT_STATE.HUNT; break; }
        this.lastKnown = t.pos.clone();
        this.faceToward(t.pos.x - this.position.x, t.pos.z - this.position.z);
        this.reactionTimer -= dt;
        if (this.reactionTimer <= 0) this.state = BOT_STATE.COMBAT;
        break;
      }
      case BOT_STATE.COMBAT: {
        const t = this.getTarget(ctx);
        if (!t) { this.state = BOT_STATE.HUNT; break; }
        this.faceToward(t.pos.x - this.position.x, t.pos.z - this.position.z);
        if (this._sees) {
          this.lastKnown = t.pos.clone();
          this.loseSightTimer = 0;
          this.combatFire(dt, ctx, t);
        } else {
          this.loseSightTimer += dt;
          if (this.loseSightTimer > 2.5) this.state = BOT_STATE.HUNT;
        }
        break;
      }
      case BOT_STATE.HUNT: {
        if (this._spotted !== null) {
          this.targetId = this._spotted;
          this._spotted = null;
          this.state = BOT_STATE.COMBAT;
          break;
        }
        if (!this.lastKnown || this.moveToward(this.lastKnown, 2.6, dt, ctx.colliders)) {
          this.state = BOT_STATE.PATROL;
        }
        this.animateLegs(ctx.time, 2.6);
        break;
      }
    }
  }

  combatFire(dt, ctx, t) {
    this.fireTimer -= dt;
    if (this.fireTimer > 0) return;
    if (this.burstLeft <= 0) this.burstLeft = 3 + Math.floor(Math.random() * 3);
    this.burstLeft--;
    this.fireTimer = this.burstLeft > 0 ? 0.11 : 0.7 + Math.random() * 0.8;
    const dist = this.position.distanceTo(t.pos);
    const hit = Math.random() < Math.max(0.04, 0.32 - dist * 0.008);
    ctx.botFire(this, t.id, hit, dist);
  }

  dispose() {
    this.scene.remove(this.group);
  }
}
